        case firstTransaction
        case lastTransaction
        case transactionCount
        case history
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: DecodingKeys.self)
        self.createdAt = try container.decode(Date.self, forKey: .createdAt)
        self.modifiedAt = try container.decodeIfPresent(Date.self, forKey: .modifiedAt)
        self.id = try container.decode(UUID.self, forKey: .id)
        self.name = try container.decode(String.self, forKey: .name)
        self.currency = try container.decode(String.self, forKey: .currency)
        self.baseBalance = try container.decode(Int.self, forKey: .baseBalance)
        self.subtype = try container.decode(String.self, forKey: .subtype)
        self.isBusiness = try container.decode(Bool.self, forKey: .isBusiness)
        self.includeInNetWorth = try container.decode(Bool.self, forKey: .includeInNetWorth)
        self.currentBalance = try container.decodeIfPresent(Int.self, forKey: .currentBalance) ?? 0
        self.group = try container.decode(String.self, forKey: .group)
        self.source = try container.decode(API.AccountSource.self, forKey: .source)
        self.bankBalance = try container.decodeIfPresent(Int.self, forKey: .bankBalance)
        self.balanceDrift = try container.decodeIfPresent(Int.self, forKey: .balanceDrift)
        self.holdingsValue = try container.decodeIfPresent(Int.self, forKey: .holdingsValue)
        self.firstTransaction = try container.decodeIfPresent(Date.self, forKey: .firstTransaction)
        self.lastTransaction = try container.decodeIfPresent(Date.self, forKey: .lastTransaction)
        self.transactionCount = try container.decode(Int.self, forKey: .transactionCount)
        self._history = try container.decode(Lossy<API.BalancePoint>.self, forKey: .history)
    }

    private enum EncodingKeys: String, CodingKey {
        case createdAt = "created_at"
        case modifiedAt = "modified_at"
        case id
        case name
        case currency
        case baseBalance = "base_balance"
        case subtype
        case isBusiness = "is_business"
        case includeInNetWorth = "include_in_net_worth"
        case currentBalance = "current_balance"
        case group
        case source
        case bankBalance = "bank_balance"
        case balanceDrift = "balance_drift"
        case holdingsValue = "holdings_value"
        case firstTransaction = "first_transaction"
        case lastTransaction = "last_transaction"
        case transactionCount = "transaction_count"
        case history
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: EncodingKeys.self)
        try container.encode(API.Instant(self.createdAt), forKey: .createdAt)
        try container.encodeIfPresent(self.modifiedAt.map(API.Instant.init), forKey: .modifiedAt)
        try container.encode(self.id, forKey: .id)
        try container.encode(self.name, forKey: .name)
        try container.encode(self.currency, forKey: .currency)
        try container.encode(self.baseBalance, forKey: .baseBalance)
        try container.encode(self.subtype, forKey: .subtype)
        try container.encode(self.isBusiness, forKey: .isBusiness)
        try container.encode(self.includeInNetWorth, forKey: .includeInNetWorth)
        try container.encode(self.currentBalance, forKey: .currentBalance)
        try container.encode(self.group, forKey: .group)
        try container.encode(self.source, forKey: .source)
        try container.encodeIfPresent(self.bankBalance, forKey: .bankBalance)
        try container.encodeIfPresent(self.balanceDrift, forKey: .balanceDrift)
        try container.encodeIfPresent(self.holdingsValue, forKey: .holdingsValue)
        try container.encodeIfPresent(self.firstTransaction.map(API.Day.init), forKey: .firstTransaction)
        try container.encodeIfPresent(self.lastTransaction.map(API.Day.init), forKey: .lastTransaction)
        try container.encode(self.transactionCount, forKey: .transactionCount)
        try container.encode(self.history, forKey: .history)
    }
}

